const page = $input.first().json;
const cutoff = Date.now() - 48*60*60*1000;
const topics = (page.topic_list && page.topic_list.topics) || [];
return topics
  .filter(t => new Date(t.created_at).getTime() > cutoff)
  .map(t => ({ json: { topic_id: String(t.id), title: t.title, excerpt: (t.excerpt || '').replace(/<[^>]+>/g, ' ').trim(), url: 'https://COMMUNITY_URL_TO_WATCH/t/' + t.id, created_at: t.created_at } }));

