={
  "contents": [{
    "parts": [{
      "text": "You are a job board assistant. Summarize the following job post in one or two sentences for a busy job seeker. Then score how relevant it is from 1 to 100 for someone looking for automation and workflow engineering roles. Reply with JSON only.\n\nTitle: {{ $json.title }}\nExcerpt: {{ $json.excerpt }}\nURL: {{ $json.url }}"
    }]
  }],
  "generationConfig": {
    "temperature": 0.2,
    "responseMimeType": "application/json",
    "responseSchema": {
      "type": "OBJECT",
      "properties": {
        "summary": { "type": "STRING" },
        "score": { "type": "INTEGER" }
      },
      "required": ["summary", "score"]
    }
  }
}

parameters.jsCode:
const items = $input.all();
const summaries = items[0].json.summaries || [];
const lines = [];
for (const s of summaries) {
  const src = s.json || s;
  const title = src.title || 'Untitled job post';
  const url = src.url || '';
  const aiText = src.candidates && src.candidates[0] && src.candidates[0].content && src.candidates[0].content.parts && src.candidates[0].content.parts[0] ? src.candidates[0].content.parts[0].text : null;
  let summaryOut = '';
  let scoreOut = 'n/a';
  if (aiText) {
    try {
      const parsed = JSON.parse(aiText);
      summaryOut = parsed.summary || '';
      scoreOut = parsed.score !== undefined ? String(parsed.score) : 'n/a';
    } catch (err) {
      summaryOut = aiText.slice(0, 200);
    }
  }
  lines.push('• ' + title + '\n' + summaryOut + '\nRelevance: ' + scoreOut + '/100\n' + url);
}
return [{ json: { digest: lines.length ? lines.join('\n\n') : 'No new job posts since the last run.' } }];
